#nullable enable

using JasperFx;
using JasperFx.Events;
using Marten;
using Marten.Exceptions;
using Allocation.Contracts;
using Allocation.Views;

namespace Allocation.Slices.Allocation;

/// <summary>
/// THE MECHANISM THIS FOLDER EXISTS TO SHOW, and it is deliberately not in the endpoint: the reserve step
/// has to be callable from a request, from a test, and from a race harness, and an endpoint is only the
/// first of those.
///
/// The rule is "a pool of N units never has more than N holders". That looks like an invariant spanning
/// every Slot stream of a pool — the shape `cross-aggregate-invariant/` needs a guard row, a unique index,
/// an advisory lock or DCB for. It is not, and the difference is the whole of Understanding EventSourcing
/// ch. 36:
///
///   > "there can only ever be one aggregate for a given ID at any point in time. So if we define the
///   >  E-Mail address as the aggregate-id, it ensures that an E-Mail can only be taken once."
///
/// ENUMERATE the resource — one stream per unit, keyed `slot:{poolId}:{n}` — and the limit stops being a
/// running total that two writers can both read. There are exactly `capacity` keys and each admits one
/// holder, so "no more than N" is arithmetic on the key space rather than a fact anybody has to defend.
/// Nothing extra is written, indexed or locked: the cheapest of the five mechanisms in the sibling folder,
/// which is exactly what BOOK-INDEX §2 gap 2 predicted before this was built.
///
/// WHAT IT COSTS, and it is not free. Contention becomes RETRIES: a reserver that loses slot 3 walks on to
/// slot 4, so taking the last unit of a nearly-full pool can take O(capacity) round trips. Compare the
/// advisory-lock arm next door, which degrades into waiting instead. And the resource has to be
/// ENUMERABLE — a budget in currency has no slot numbers, which is why that folder exists and this trick
/// does not retire it.
/// </summary>
public static class SlotReservation
{
    public const string PoolNotOpen = "PoolNotOpen";
    public const string PoolExhausted = "PoolExhausted";

    public sealed record Reservation(Guid PoolId, int SlotNumber, Guid GrantId);

    public sealed record Result(SliceOutcome Outcome, Reservation? Reserved = null, int Attempts = 0);

    /// <summary>
    /// Take one unit of <paramref name="poolId"/> for <paramref name="grantId"/>, or refuse.
    ///
    /// The order of the three reads matters and each is a different KIND of read:
    ///   1. capacity, from the Pool stream — cross-stream, but of a value nothing ever rewrites
    ///   2. the availability view — A HINT. Stale by construction, and consulted only to choose which slot
    ///      to try FIRST. It cannot make this wrong, only slower.
    ///   3. the slot's own stream, under FetchForWriting — the only read that decides anything, and the
    ///      only one whose version is checked at save.
    /// </summary>
    public static async Task<Result> Reserve(
        IDocumentStore store, Guid poolId, Guid grantId, CancellationToken cancellation = default)
    {
        int capacity;
        int[] hintTaken;

        await using (var read = store.LightweightSession())
        {
            // FetchLatest on IDocumentSession.Events, not the query session — reading another stream is a
            // read and adds no check at save time, which is correct here: capacity is not the contended
            // thing, and there IS no contended total.
            var pool = await read.Events.FetchLatest<OpenPoolState>(
                OpenPoolState.StreamKey(poolId.ToString()), cancellation);

            if (pool is not { Opened: true })
                return new Result(SliceOutcome.Rejected(PoolNotOpen,
                    $"Pool {poolId} has not been opened, so it has no units to reserve."));

            capacity = pool.Capacity;

            // THE HINT, and note what happens when it is missing or wrong: nothing. An absent row (the
            // daemon has not caught up, or this is the first reservation ever) leaves the candidate order
            // as 1..capacity, which is also the correct order. A row naming slots that have since been
            // released merely tries them last. This is the read that would be a bug if the LIMIT depended
            // on it — ANTI-PATTERNS #17 — and it is safe only because the limit does not.
            var hint = await read.LoadAsync<PoolAvailability>(poolId, cancellation);
            hintTaken = hint?.TakenSlots ?? [];
        }

        // Slots the hint believes are free, lowest first; then the rest, lowest first. A stale hint costs
        // position in this list and nothing else.
        var candidates = Enumerable.Range(1, capacity)
            .OrderBy(n => hintTaken.Contains(n) ? 1 : 0)
            .ThenBy(n => n)
            .ToArray();

        var attempts = 0;
        foreach (var slotNumber in candidates)
        {
            attempts++;

            // A FRESH SESSION PER ATTEMPT. A session that has failed SaveChangesAsync still holds the
            // staged append, so reusing it would try to write the losing event again on the next slot and
            // silently double-book. Cheap, and the alternative is a bug that only appears under contention.
            await using var session = store.LightweightSession();

            var stream = await session.Events.FetchForWriting<ReserveSlotState>(
                ReserveSlotState.StreamKey(poolId, slotNumber), cancellation);

            // Held is the SEQUENTIAL guard: this unit is taken, walk on. It is also what makes a RELEASED
            // slot reservable again — the stream exists, so a create-collision would refuse it for ever.
            if (stream.Aggregate is { Held: true }) continue;

            stream.AppendOne(new SlotReserved(poolId, slotNumber, grantId, DateTimeOffset.UtcNow));

            try
            {
                await session.SaveChangesAsync(cancellation);
                return new Result(SliceOutcome.Ok(), new Reservation(poolId, slotNumber, grantId), attempts);
            }
            catch (Exception ex) when (IsLostRace(ex))
            {
                // SOMEBODY ELSE TOOK THIS UNIT between our fetch and our save. That is the mechanism
                // working, not an error: walk on to the next candidate. Three exception types reach here
                // and they are the same verdict —
                //   ExistingStreamIdCollisionException  we both tried to CREATE slot n; they got there first
                //   EventStreamUnexpectedMaxEventIdException / ConcurrencyException
                //                                       the stream already existed and moved under us
                // Distinguishing them would be describing Postgres, not the domain.
                continue;
            }
        }

        // Every unit is held. THIS IS THE LIMIT, and note it was never enforced by a total: it is what
        // running out of stream keys looks like.
        return new Result(SliceOutcome.Rejected(PoolExhausted,
            $"Every one of pool {poolId}'s {capacity} units is currently held."), Attempts: attempts);
    }

    /// <summary>
    /// Matched on NAME rather than type, for the reason ConcurrencyHarness gives: these have moved
    /// namespace between Marten majors (ConcurrencyException is in JasperFx as of 9, not Marten.Exceptions)
    /// and a reference implementation that pins itself to one of them ages badly.
    /// </summary>
    private static bool IsLostRace(Exception ex) => ex.GetType().Name is
        nameof(ExistingStreamIdCollisionException) or
        nameof(EventStreamUnexpectedMaxEventIdException) or
        nameof(ConcurrencyException);
}
